import org.openenglish.reader.*;
import java.util.*;
import java.util.concurrent.*;
public class VoiceFlowTest {
 static int checks;
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static short[] frame(int amplitude){short[] x=new short[VoiceGate.FRAME];Arrays.fill(x,(short)amplitude);return x;}
 static class Listen implements VoiceGate.Listener {int starts,ends;float[] pcm;boolean clipped;public void start(){starts++;}public void end(float[] p,boolean c){ends++;pcm=p;clipped=c;}}
 static void frames(VoiceGate g,int n,boolean speech){for(int i=0;i<n;i++)g.frame(frame(speech?2000:0),speech);}
 public static void main(String[] args)throws Exception {
  Listen l=new Listen();VoiceGate g=new VoiceGate(360,l);frames(g,40,false);check(l.starts==0&&l.ends==0,"silence causes no turn");frames(g,3,true);frames(g,12,false);check(l.starts==0,"short transient does not interrupt");
  frames(g,4,true);check(l.starts==1&&g.speaking(),"four neural speech frames trigger onset");frames(g,4,true);frames(g,11,false);check(l.ends==0,"utterance not ended before rounded silence interval");frames(g,1,false);check(l.ends==1&&!g.speaking(),"utterance ends at twelve 32ms quiet frames");check(l.pcm.length==VoiceGate.FRAME*17&&l.pcm[0]==0,"pre-roll preserves audio before onset");check(l.pcm.length<=VoiceGate.RATE*18,"utterance memory bounded");
  frames(g,8,true);frames(g,3,false);frames(g,8,true);frames(g,12,false);check(l.starts==2&&l.ends==2,"brief hesitation retains a single turn");
  Listen shortVoice=new Listen();VoiceGate shortGate=new VoiceGate(360,shortVoice);frames(shortGate,4,true);frames(shortGate,12,false);check(shortVoice.starts==1&&shortVoice.ends==1,"short Yes/No answers are submitted to ASR");
  Listen longVoice=new Listen();VoiceGate longGate=new VoiceGate(360,longVoice);frames(longGate,563,true);check(longVoice.ends==1&&longVoice.clipped&&longVoice.pcm.length==VoiceGate.RATE*18,"continuous detected speech submits at eighteen seconds without waiting for silence");frames(longGate,12,false);
  frames(g,8,true);g.reset();frames(g,12,false);check(l.ends==2&&!g.speaking(),"pause resets partial utterance");
  Listen stable=new Listen();VoiceGate neural=new VoiceGate(360,stable);for(int i=0;i<50;i++)neural.frame(frame(20000),false);check(stable.starts==0,"loud audio rejected when neural detector says non-speech");
  check(VoiceGate.rms(frame(0))==0&&VoiceGate.rms(frame(2000))>.05,"real PCM meter calculation");
  SpeechChunks chunks=new SpeechChunks();check(chunks.accept("Hello",false).isEmpty(),"incomplete word group waits");check(chunks.accept("Hello there.",false).equals(Collections.singletonList("Hello there.")),"finished sentence speaks before generation ends");check(chunks.accept("Hello there. How are",false).isEmpty(),"spoken prefix is not repeated");check(chunks.accept("Hello there. How are you?",true).equals(Collections.singletonList("How are you?")),"final sentence only once");check(chunks.accept("Hello there. How are you?",true).isEmpty(),"duplicate final callback does not repeat speech");
  chunks.clear();String longSentence="This is a longer sentence with several words that can be spoken before the final punctuation arrives";List<String> early=chunks.accept(longSentence,false);check(!early.isEmpty()&&early.get(0).length()>=38,"early complete-word chunk reduces first speech wait");List<String> tail=chunks.accept(longSentence,true);String restored=String.join(" ",early)+" "+String.join(" ",tail);check(restored.equals(longSentence),"chunking preserves every word once");
  chunks.clear();check(chunks.accept("bad\ufffd",false).isEmpty(),"incomplete UTF-8 token is not spoken");check(chunks.accept("Hi 😀!",true).equals(Collections.singletonList("Hi 😀!")),"Unicode survives TTS chunking");chunks.clear();check(chunks.accept("New turn",true).equals(Collections.singletonList("New turn")),"barge-in clears previous stream cursor");
  chunks.clear();check(chunks.accept("It costs 3.",false).isEmpty(),"streamed decimal waits for its next token");check(chunks.accept("It costs 3.50 dollars.",true).equals(Collections.singletonList("It costs 3.50 dollars.")),"decimal remains in one spoken phrase");
  chunks.clear();chunks.accept("Hello there.",false);check(chunks.accept("Hi there. More words",true).isEmpty(),"revision of spoken prefix never emits an unrelated suffix");check(chunks.accept("Hello there. New words",true).equals(Collections.singletonList("New words")),"stable spoken prefix resumes after a temporary revision");
  Listen balanced=new Listen();VoiceGate balancedGate=new VoiceGate(600,balanced);frames(balancedGate,4,true);frames(balancedGate,19,false);check(balanced.pcm.length==VoiceGate.FRAME*9,"balanced endpoint silence is trimmed to 160 ms too");
  chunks.clear();check(chunks.accept("Hello!",false).equals(Collections.singletonList("Hello!")),"single greeting speaks before generation finishes");check(chunks.accept("Hello! What would you like?",false).equals(Collections.singletonList("What would you like?")),"following question does not replay greeting");check(chunks.accept("Hello! What would you like?",true).isEmpty(),"final greeting stream does not replay its first chunk");chunks.clear();check(chunks.accept("Yes.",true).equals(Collections.singletonList("Yes.")),"legitimate final one-word answer still plays");
  VoiceTurns turns=new VoiceTurns();long old=turns.next(),fresh=turns.next();check(!turns.current(old)&&turns.current(fresh),"late recognition and tokens invalidated immediately");int[] writes={0};check(!turns.commit(old,()->writes[0]++)&&writes[0]==0,"interrupted reply cannot enter conversation memory");check(turns.commit(fresh,()->writes[0]++)&&writes[0]==1,"completed current reply commits once");
  CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);Thread commit=new Thread(()->turns.commit(fresh,()->{entered.countDown();try{release.await();}catch(InterruptedException e){throw new RuntimeException(e);}}));commit.start();check(entered.await(2,TimeUnit.SECONDS),"commit boundary entered");CountDownLatch invalidating=new CountDownLatch(1);Thread invalidate=new Thread(()->{invalidating.countDown();turns.next();});invalidate.start();check(invalidating.await(2,TimeUnit.SECONDS),"invalidation competes with write");release.countDown();commit.join(2000);invalidate.join(2000);check(!commit.isAlive()&&!invalidate.isAlive()&&!turns.current(fresh),"write and invalidation finish in a consistent order");
  ExecutorService pool=Executors.newFixedThreadPool(4);Set<Long> ids=ConcurrentHashMap.newKeySet();try{List<Future<?>> tasks=new ArrayList<>();for(int i=0;i<4;i++)tasks.add(pool.submit(()->{for(int n=0;n<1000;n++)ids.add(turns.next());}));for(Future<?> f:tasks)f.get();check(ids.size()==4000&&turns.current()==4003,"concurrent turn epochs never collide");}finally{pool.shutdownNow();}
  System.out.println("VOICE_FLOW_CHECKS: "+checks);
 }
}
